package io.fabric8.kubernetes.client.utils.internal;

import io.fabric8.kubernetes.api.model.*;
import io.fabric8.kubernetes.api.model.extensions.*;
import io.fabric8.kubernetes.client.utils.URLUtils;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;

public class URLFromServiceUtil {
  public static final Logger logger = LoggerFactory.getLogger(URLFromServiceUtil.class);
  public static final String DEFAULT_PROTO = "tcp";
  private static final String HOST_SUFFIX = "_SERVICE_HOST";
  private static final String PORT_SUFFIX = "_SERVICE_PORT";
  private static final String PROTO_SUFFIX = "_TCP_PROTO";

  private URLFromServiceUtil() {
    throw new IllegalStateException("Utility class");
  }

  public static String resolveHostFromEnvVarOrSystemProperty(String serviceName) {
    return getEnvVarOrSystemProperty(toServiceHostEnvironmentVariable(serviceName), "");
  }

  private static String getEnvVarOrSystemProperty(String envVarName, String defaultValue) {
    String answer = null;
    try {
      answer = System.getenv(envVarName);
    } catch (Exception e) {
      logger.warn("Failed to look up environment variable $" + envVarName + ". " + e, e);
    }
    if (answer == null || answer.isEmpty()) {
      answer = System.getProperty(envVarName, defaultValue);
    }
    if (!answer.isEmpty()) {
      return answer;
    } else {
      return defaultValue;
    }
  }

  public static String resolveProtocolFromEnvVarOrSystemProperty(String serviceName, String servicePort) {
    return getEnvVarOrSystemProperty(toEnvVariable(serviceName + "_PORT_" + servicePort + PROTO_SUFFIX),
        DEFAULT_PROTO);
  }

  public static Map<String, String> getOrCreateAnnotations(HasMetadata entity) {
    ObjectMeta metadata = getOrCreateMetadata(entity);
    Map<String, String> answer = metadata.getAnnotations();
    if (answer == null) {
      // use linked so the annotations can be in the FIFO order
      answer = new LinkedHashMap<>();
      metadata.setAnnotations(answer);
    }
    return answer;
  }

  public static ObjectMeta getOrCreateMetadata(HasMetadata entity) {
    ObjectMeta metadata = entity.getMetadata();
    if (metadata == null) {
      metadata = new ObjectMeta();
      entity.setMetadata(metadata);
    }
    return metadata;
  }

  public static String resolvePortFromEnvVarOrSystemProperty(String serviceName, String portName) {
    String envVarName = toServicePortEnvironmentVariable(serviceName, portName);
    return getEnvVarOrSystemProperty(envVarName, "");
  }

  public static String toServicePortEnvironmentVariable(String serviceName, String portName) {
    String name = serviceName + PORT_SUFFIX + (portName.isEmpty() ? "" : "_" + portName);
    return toEnvVariable(name);
  }

  private static String toServiceHostEnvironmentVariable(String serviceName) {
    return toEnvVariable(serviceName + HOST_SUFFIX);
  }

  public static String toEnvVariable(String serviceName) {
    return serviceName.toUpperCase(Locale.ROOT).replaceAll("-", "_");
  }

  /**
   * Resolves a service URL from a list of {@code networking.k8s.io/v1} Ingresses.
   *
   * @param ingressList list of networking.v1 Ingresses
   * @param namespace   namespace the service belongs to
   * @param serviceName name of the service to look up
   * @param port        service port to match against the ingress backend
   * @return an https URL if TLS is configured for the matching host, an http URL otherwise, or null if not found
   */
  public static String getURLFromNetworkingV1IngressList(
      List<io.fabric8.kubernetes.api.model.networking.v1.Ingress> ingressList, String namespace, String serviceName,
      ServicePort port) {
    if (ingressList == null || ingressList.isEmpty()) {
      return null;
    }
    for (io.fabric8.kubernetes.api.model.networking.v1.Ingress ingress : ingressList) {
      String ns = getNamespace(ingress);
      if (!Objects.equals(ns, namespace) || ingress.getSpec() == null) {
        continue;
      }
      io.fabric8.kubernetes.api.model.networking.v1.IngressSpec spec = ingress.getSpec();
      List<io.fabric8.kubernetes.api.model.networking.v1.IngressRule> rules = spec.getRules();
      if (rules == null || rules.isEmpty()) {
        continue;
      }
      for (io.fabric8.kubernetes.api.model.networking.v1.IngressRule rule : rules) {
        io.fabric8.kubernetes.api.model.networking.v1.HTTPIngressRuleValue http = rule.getHttp();
        if (http == null || http.getPaths() == null) {
          continue;
        }
        String url = getURLFromNetworkingV1IngressRule(http.getPaths(), spec, serviceName, port, rule);
        if (url != null) {
          return url;
        }
      }
    }
    return null;
  }

  private static String getURLFromNetworkingV1IngressRule(
      List<io.fabric8.kubernetes.api.model.networking.v1.HTTPIngressPath> paths,
      io.fabric8.kubernetes.api.model.networking.v1.IngressSpec spec, String serviceName, ServicePort port,
